mapper.select:
SELECT symbol
FROM t_risk_config
WHERE market_code = #{marketCode}

mapper.update:
UPDATE t_risk_config
SET direction_imbalance_ratio_threshold = #{ratioThreshold},
    direction_imbalance_min_total_usd   = #{minTotalUsd},
    updated_at                          = #{updatedAt}
WHERE symbol = #{symbol}

UPDATE t_risk_config
SET cooling_period_seconds = #{coolingPeriodSeconds}
WHERE symbol IS NULL
